/**
 * Nobody's Simple — independent, clinically cautious question library for
 * deeper personalised formulation. Nothing from third-party guessing games
 * is reproduced or adapted here.
 *
 * Signals are editorial *compatibility indicators*, not validated
 * likelihood ratios, Bayes factors, clinical probabilities or diagnoses.
 */
const P=(id,title,description,possibleFunction,possibleCost,need,check,link,tracks)=>
 Object.freeze({id,title,description,possibleFunction,possibleCost,need,check,link,tracks:Object.freeze(tracks)});
