export const DEEP_BY_ID=Object.freeze(Object.fromEntries(DEEP_PROCESSES.map(p=>[p.id,p])));
export const EXTRA_BY_TRACK=Object.freeze(Object.fromEntries(
 ['procrastination','overthinking','relationships','social','fatigue','emotion','sleep','checking','choices','identity','sensory','loss']
  .map(t=>[t,Object.freeze(DEEP_PROCESSES.filter(p=>p.tracks.includes(t)).map(p=>p.id))])
));
/**
 * Every question has tags for what the answer says about the formulation,
 * optional branch conditions and the user-visible reason for asking.
 */
const Q=(id,prompt,why,signals,tracks,tags,priority=1.5,when='')=>
 Object.freeze({id:'d-'+id,prompt,why,signals:Object.freeze({...signals}),
  tracks:Object.freeze(tracks),tags:Object.freeze(tags),priority,when});
