export const DEEP_QUESTION_BY_ID=Object.freeze(Object.fromEntries(DEEP_QUESTIONS.map(q=>[q.id,q])));
const presentationRegex=/shav(?:e|es|ed|ing)|hairless|groom|clothes|cloth(?:ing|es)|dress(?:ing)?|make.?up|nail polish|appearance|presentation|presenting|feminin|masculin|boy.?wife|cross.?dress|gender.expression|look like|wear(?:ing)? (?:a |the )?(?:skirt|dress|heels)|legs (?:smooth|shaved)/i;
export const isPresentationQuery=description=>presentationRegex.test(String(description||''));
export const presentationBranchActive=state=>{
 if(state?.trackId!=='identity')return false;
 if(isPresentationQuery(state.description))return true;
 return state.answers.some(a=>a.questionId==='d-id-presentation'&&['yes','probably'].includes(a.answerId));
};
